1	// Package httpapi exposes the event timeline over HTTP.
2	package httpapi
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"errors"
8		"io"
9		"net/http"
10		"time"
11	
12		"github.com/cocosolocoder/signalroom/internal/events"
13		"github.com/cocosolocoder/signalroom/internal/incidents"
14		"github.com/cocosolocoder/signalroom/internal/metrics"
15	)
16	
17	// maxBodyBytes bounds a single POST request body.
18	const maxBodyBytes = 16 << 20
19	
20	// Storage durably persists a batch before it becomes visible.
21	type Storage interface {
22		Append(batch []events.Event) error
23		Poisoned() bool
24	}
25	
26	type envelope struct {
27		Events json.RawMessage `json:"events"`
28	}
29	
30	// Handler wires the timeline, its durable log, and the cursor store to HTTP
31	// routes.
32	type Handler struct {
33		timeline *events.Timeline
34		log      Storage
35		cursors  CursorStore
36	
37		incidents    *incidents.Registry
38		incidentLogs IncidentStorage
39	
40		metrics    *metrics.Store
41		metricLogs MetricStorage
42	
43		mux *http.ServeMux
44	}
45	
46	// Option customizes a Handler at construction.
47	type Option func(*Handler)
48	
49	// WithIncidents enables the incident endpoints, backed by reg and its
50	// durable store.
51	func WithIncidents(reg *incidents.Registry, store IncidentStorage) Option {
52		return func(h *Handler) {
53			h.incidents = reg
54			h.incidentLogs = store
55		}
56	}
57	
58	// WithMetrics enables the metric endpoints, backed by store and its durable
59	// log.
60	func WithMetrics(store *metrics.Store, log MetricStorage) Option {
61		return func(h *Handler) {
62			h.metrics = store
63			h.metricLogs = log
64		}
65	}
66	
67	// NewHandler builds the HTTP handler for a timeline backed by log. cursors
68	// supplies the per-directory signing key and snapshot storage for paging.
69	func NewHandler(timeline *events.Timeline, log Storage, cursors CursorStore, opts ...Option) *Handler {
70		h := &Handler{timeline: timeline, log: log, cursors: cursors, mux: http.NewServeMux()}
71		for _, opt := range opts {
72			opt(h)
73		}
74		h.mux.HandleFunc("/events", h.events)
75		h.mux.HandleFunc("/alerts/preview", h.previewAlerts)
76		h.mux.HandleFunc("/events/compare", h.compareEvents)
77		h.mux.HandleFunc("/events/page", h.pageEvents)
78		if h.metrics != nil {
79			h.mux.HandleFunc("/metrics", h.metricsRoot)
