		"empty":      {`,"labels":{}`, nil},
		"populated":  {`,"labels":{"env":"prod","version":"v2"}`, map[string]string{"env": "prod", "version": "v2"}},
		"whitespace": {`,"labels":{" env ":" prod "}`, map[string]string{" env ": " prod "}},
