	cases := map[string]string{
		"duplicate keys":   `"labels":{"env":"a","env":"a"}`,
		"duplicate differ": `"labels":{"env":"a","env":"b"}`,
		"number value":     `"labels":{"env":1}`,
		"bool value":       `"labels":{"env":true}`,
		"null value":       `"labels":{"env":null}`,
