	if !present || bytes.Equal(raw, []byte("null")) {
		writeError(w, http.StatusBadRequest, name+" is required")
		return false
	}
	if !isDecimal(string(raw)) {
		writeError(w, http.StatusBadRequest, name+" has the wrong type")
