	trimmed := bytes.TrimSpace(rawSamples)
	if !present || bytes.Equal(trimmed, []byte("null")) || bytes.Equal(trimmed, []byte("[]")) {
		writeError(w, http.StatusBadRequest, "samples must be a non-empty array")
